    <header>
        <h1>MapleSure Insurance</h1>
    </header>
    <div class="container">
        <form id="claim-form">
            <h2>Submit a Disability Claim</h2>
            <div>
                <label for="policy-number">Policy Number</label>
                <input type="text" id="policy-number" required>
            </div>
            <div>
                <label for="member-id">Member ID</label>
                <input type="text" id="member-id" required>
            </div>
            <div>
                <button type="button" onclick="lookupMember()">Look up member</button>
            </div>
            <div id="member-details">
                <!-- Member details panel placeholder -->
                <p>Member details will appear here after lookup.</p>
            </div>
            <div>
                <label for="last-day-worked">Last Day Worked</label>
                <input type="date" id="last-day-worked" required>
            </div>
            <div>
                <label for="first-day-absent">First Day Absent</label>
                <input type="date" id="first-day-absent" required>
            </div>
            <div>
                <label for="nature-of-absence">Nature of Absence</label>
                <select id="nature-of-absence" required>
                    <option value="">Select...</option>
                    <option value="illness">Illness</option>
                    <option value="injury">Injury</option>
                    <option value="personal">Personal</option>
                </select>
            </div>
            <div>
                <label for="details">Details</label>
                <textarea id="details" rows="4"></textarea>
            </div>
            <div>
                <label for="documents">Upload Documents</label>
                <input type="file" id="documents" multiple onchange="updateFileList()">
                <ul id="file-list"></ul>
            </div>
            <button type="submit" onclick="submitForm(event)">Submit Claim</button>
        </form>
        <div id="confirmation" class="hidden">
            <h2>Claim Submission</h2>
            <p class="confirmation-msg">Reference Number: <span id="ref-number"></span></p>
            <p class="confirmation-msg">Status: Received</p>
        </div>
    </div>
    <footer>
        <p>MapleSure Insurance  fictional demo application</p>
    </footer>

    <script>
        // Mock data object for member lookup
        const mockMembers = {
            "12345": "John Doe",
            "67890": "Jane Smith"
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');

            if (mockMembers[memberId]) {
                memberDetails.innerHTML = `<p>Member Name: ${mockMembers[memberId]}</p>`;
            } else {
                memberDetails.innerHTML = '<p>Member not found.</p>';
            }
        }

        function updateFileList() {
            const input = document.getElementById('documents');
            const fileList = document.getElementById('file-list');

            fileList.innerHTML = '';
            for (let i = 0; i < input.files.length; i++) {
                const li = document.createElement('li');
                li.textContent = input.files[i].name;
                fileList.appendChild(li);
            }
        }

        function submitForm(event) {
            event.preventDefault();
            const form = document.getElementById('claim-form');
            form.classList.add('hidden');

            const confirmation = document.getElementById('confirmation');
            confirmation.classList.remove('hidden');
            document.getElementById('ref-number').textContent = generateReferenceNumber();
        }

        function generateReferenceNumber() {
            const date = new Date();
            const year = date.getFullYear();
            const month = ('0' + (date.getMonth() + 1)).slice(-2);
            const randomPart = Math.floor(1000 + Math.random() * 9000);
            return `MS-${year}-${month}-${randomPart}`;
        }
    </script>
</body>
